window.REV_FLIP=window.REV_FLIP||{};window.REV_FLIP["pytorch-hands-on"]=[{"id":"pytorch-hands-on-f0001","card":"q-pytorch-hands-on-001-1-pytorch-at-a-glance","sec":"pytorch-hands-on-s002","q":"What is PyTorch, and what are its four pillars?","a":"<p>An open-source deep learning framework from <strong>Meta</strong>. The pillars are <strong>Tensors, Autograd, API, Libraries</strong>.</p>","hand":true},{"id":"pytorch-hands-on-f0002","card":"q-pytorch-hands-on-001-1-pytorch-at-a-glance","sec":"pytorch-hands-on-s002","q":"What are the four main strengths of PyTorch?","a":"<ul>\n  <li>Dynamic computation graph: the graph is built as operations run, so debugging is plain Python.</li>\n  <li>Pythonic: fits the Python ecosystem.</li>\n  <li>GPU acceleration: fast training and inference.</li>\n  <li>Prototyping to production: TorchServe for serving, TorchScript for optimization.</li>\n</ul>","hand":true},{"id":"pytorch-hands-on-f0003","card":"q-pytorch-hands-on-001-1-pytorch-at-a-glance","sec":"pytorch-hands-on-s002","q":"How is the PyTorch API layered (hybrid API design)?","a":"<p>A Python user API (<code>torch</code>, <code>torch.nn</code>, <code>torch.optim</code>, <code>torch.utils.data</code>) sits on top. Below it is a C++ core (ATen: tensor library, serialization), and below that CUDA kernels for NVIDIA GPUs. This gives Python ease plus C++/CUDA speed.</p>","hand":true},{"id":"pytorch-hands-on-f0004","card":"q-pytorch-hands-on-001-1-pytorch-at-a-glance","sec":"pytorch-hands-on-s002","q":"What is a PyTorch tensor?","a":"<p>A multidimensional array with GPU support and autograd tracking.</p>","hand":true},{"id":"pytorch-hands-on-f0005","card":"q-pytorch-hands-on-001-1-pytorch-at-a-glance","sec":"pytorch-hands-on-s002","q":"How do you convert a tensor to NumPy and back, change its dtype, and move it to the GPU?","a":"<p>Use <code>.numpy()</code> and <code>torch.from_numpy()</code> for NumPy. Cast dtype with <code>.to(dtype=...)</code>. Move device with <code>.to('cuda')</code>.</p>","hand":true},{"id":"pytorch-hands-on-f0006","card":"q-pytorch-hands-on-001-1-pytorch-at-a-glance","sec":"pytorch-hands-on-s002","q":"What is autograd in PyTorch, and what is its goal?","a":"<p>The automatic differentiation engine. The goal is to minimize the loss by adjusting weights, and gradients say which direction to change each weight.</p>","hand":true},{"id":"pytorch-hands-on-f0007","card":"q-pytorch-hands-on-001-1-pytorch-at-a-glance","sec":"pytorch-hands-on-s002","q":"How do you check the installed PyTorch version?","a":"<p>Print <code>torch.__version__</code>.</p>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Python</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>import torch\nprint(torch.__version__)  # 2.8.0</code></pre></div>","hand":true},{"id":"pytorch-hands-on-f0008","card":"q-pytorch-hands-on-001-1-pytorch-at-a-glance","sec":"pytorch-hands-on-s002","q":"What does the dynamic computation graph mean for debugging in PyTorch?","a":"<p>The graph is built as operations run, so debugging is plain Python.</p>","hand":true},{"id":"pytorch-hands-on-f0009","card":"q-pytorch-hands-on-002-libraries","sec":"pytorch-hands-on-s003","q":"What does each core PyTorch library do: <code>torch</code>, <code>torch.nn</code>, <code>torch.optim</code>, <code>torch.autograd</code>, <code>torch.utils.data</code>?","a":"<div class=\"table-wrap\">\n  <table>\n    <thead><tr><th>Library</th><th>Purpose</th></tr></thead>\n    <tbody>\n      <tr><td><code>torch</code></td><td>Tensors, autograd, base workflows</td></tr>\n      <tr><td><code>torch.nn</code></td><td>Layers (<code>Linear</code>, <code>Conv2d</code>), losses, activations</td></tr>\n      <tr><td><code>torch.optim</code></td><td>Optimizers: SGD, Adam, RMSprop</td></tr>\n      <tr><td><code>torch.autograd</code></td><td>Automatic differentiation</td></tr>\n      <tr><td><code>torch.utils.data</code></td><td><code>Dataset</code>, <code>DataLoader</code></td></tr>\n    </tbody>\n  </table>\n</div>","hand":true},{"id":"pytorch-hands-on-f0010","card":"q-pytorch-hands-on-002-libraries","sec":"pytorch-hands-on-s003","q":"Which PyTorch supporting library covers each domain: vision, audio, NLP, serving, multi-GPU training?","a":"<div class=\"table-wrap\">\n  <table>\n    <thead><tr><th>Library</th><th>Domain</th></tr></thead>\n    <tbody>\n      <tr><td>TorchVision</td><td>Vision: pretrained models, datasets, transforms</td></tr>\n      <tr><td>TorchAudio</td><td>Audio: datasets, transforms, speech models</td></tr>\n      <tr><td>TorchText</td><td>NLP: datasets, preprocessing, embeddings</td></tr>\n      <tr><td>TorchServe</td><td>Serve models at scale with REST APIs</td></tr>\n      <tr><td><code>torch.distributed</code></td><td>Multi-GPU / multi-node training</td></tr>\n    </tbody>\n  </table>\n</div>","hand":true},{"id":"pytorch-hands-on-f0011","card":"q-pytorch-hands-on-002-libraries","sec":"pytorch-hands-on-s003","q":"What are the PyTorch advanced tools <code>torch.compile</code>, <code>torch.jit</code>, <code>torch.fx</code> and <code>torch.multiprocessing</code> for?","a":"<ul>\n  <li><code>torch.compile</code>: compile models for speed (2.x).</li>\n  <li><code>torch.jit</code> / TorchScript: static graph, export without Python runtime.</li>\n  <li><code>torch.fx</code>: program transformation and analysis.</li>\n  <li><code>torch.multiprocessing</code>: parallel data loading / distributed training.</li>\n</ul>","hand":true},{"id":"pytorch-hands-on-f0012","card":"q-pytorch-hands-on-002-libraries","sec":"pytorch-hands-on-s003","q":"Name the PyTorch ecosystem add-ons and what each does.","a":"<ul>\n  <li><strong>PyTorch Lightning</strong>: less boilerplate.</li>\n  <li><strong>Hugging Face Transformers</strong>: NLP/multimodal models.</li>\n  <li><strong>fastai</strong>.</li>\n  <li><strong>docTR</strong>: OCR.</li>\n  <li><strong>vLLM</strong>: high-throughput LLM inference.</li>\n  <li><strong>DeepSpeed</strong>: distributed training, from Microsoft.</li>\n  <li><strong>depyf</strong>: debug compiler bytecode.</li>\n</ul>","hand":true},{"id":"pytorch-hands-on-f0013","card":"q-pytorch-hands-on-003-2-environment-setup","sec":"pytorch-hands-on-s004","q":"How do you get the right PyTorch install command for your machine?","a":"<p>Use the selection grid at pytorch.org (Get Started, Start Locally). It generates the pip command for your OS and compute platform (CPU is the default on macOS, CUDA for GPU).</p>","hand":true},{"id":"pytorch-hands-on-f0014","card":"q-pytorch-hands-on-003-2-environment-setup","sec":"pytorch-hands-on-s004","q":"Which command installs PyTorch and TorchVision with pip, and what else does it pull in?","a":"<p><code>pip3 install torch torchvision</code>. It also pulls numpy, pillow, torchaudio and typing-extensions.</p>","hand":true},{"id":"pytorch-hands-on-f0015","card":"q-pytorch-hands-on-003-2-environment-setup","sec":"pytorch-hands-on-s004","q":"How do you pin PyTorch to version 2.2.0, and why would you?","a":"<p>Run the command below. Pinning is needed for the TorchText lab.</p>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Bash</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>pip3 install torch==2.2.0 torchvision   # pin a version (needed for the TorchText lab)</code></pre></div>","hand":true},{"id":"pytorch-hands-on-f0016","card":"q-pytorch-hands-on-003-2-environment-setup","sec":"pytorch-hands-on-s004","q":"What do you do if <code>pip3</code> is not found, and how do you launch Jupyter?","a":"<p>Run <code>python -m ensurepip --upgrade</code> and retry. Install Jupyter with <code>pip3 install jupyter</code> and launch it with <code>python3 -m notebook</code>, which opens in the browser.</p>","hand":true},{"id":"pytorch-hands-on-f0017","card":"q-pytorch-hands-on-004-3-datasets-and-dataloaders","sec":"pytorch-hands-on-s005","q":"What is the \"Project Piraeus\" use case in the PyTorch Hands-On course?","a":"<p>A platform that matches learners with tutors using ML. The labs use images (vision), audio (transcription) and text (NLP).</p>","hand":true},{"id":"pytorch-hands-on-f0018","card":"q-pytorch-hands-on-004-3-datasets-and-dataloaders","sec":"pytorch-hands-on-s005","q":"In PyTorch, what is the difference between <code>Dataset</code> and <code>DataLoader</code>?","a":"<p><code>torch.utils.data.Dataset</code> stores samples and labels. <code>torch.utils.data.DataLoader</code> does batching, shuffling and parallel loading.</p>","hand":true},{"id":"pytorch-hands-on-f0019","card":"q-pytorch-hands-on-004-3-datasets-and-dataloaders","sec":"pytorch-hands-on-s005","q":"Which preloaded datasets do TorchVision, TorchText and TorchAudio provide?","a":"<ul>\n  <li><code>torchvision.datasets</code>: FashionMNIST, CIFAR10, ImageNet.</li>\n  <li><code>torchtext.datasets</code>: IMDb, AG_NEWS.</li>\n  <li><code>torchaudio.datasets</code>: LIBRISPEECH.</li>\n</ul>","hand":true},{"id":"pytorch-hands-on-f0020","card":"q-pytorch-hands-on-005-fashionmnist-preloaded-with-train-valida","sec":"pytorch-hands-on-s006","q":"How do you load FashionMNIST training and test sets in PyTorch?","a":"<p>Use <code>datasets.FashionMNIST</code>. Only <code>train=True/False</code> differs between the two.</p>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Python</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>training_data = datasets.FashionMNIST(\n    root=&quot;data&quot;, train=True, download=True, transform=ToTensor())\ntest_data = datasets.FashionMNIST(\n    root=&quot;data&quot;, train=False, download=True, transform=ToTensor())</code></pre></div>","hand":true},{"id":"pytorch-hands-on-f0021","card":"q-pytorch-hands-on-005-fashionmnist-preloaded-with-train-valida","sec":"pytorch-hands-on-s006","q":"How do you carve a validation set from the training data in PyTorch?","a":"<p>Use <code>SubsetRandomSampler</code> on shuffled indices.</p>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Python</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>indices = list(range(len(training_data)))\nnp.random.shuffle(indices)\nsplit = int(np.floor(0.2 * len(training_data)))\ntrain_sample = SubsetRandomSampler(indices[:split])\nvalidate_sample = SubsetRandomSampler(indices[split:])</code></pre></div>","hand":true},{"id":"pytorch-hands-on-f0022","card":"q-pytorch-hands-on-005-fashionmnist-preloaded-with-train-valida","sec":"pytorch-hands-on-s006","q":"How do you build the train, validation and test DataLoaders for FashionMNIST?","a":"<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Python</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>trainloader = torch.utils.data.DataLoader(training_data, sampler=train_sample, batch_size=64)\nvalidloader = torch.utils.data.DataLoader(training_data, sampler=validate_sample, batch_size=64)\ntestloader = torch.utils.data.DataLoader(test_data, batch_size=64, shuffle=True)</code></pre></div>","hand":true},{"id":"pytorch-hands-on-f0023","card":"q-pytorch-hands-on-005-fashionmnist-preloaded-with-train-valida","sec":"pytorch-hands-on-s006","q":"What is the gotcha in the course's FashionMNIST train/validation split code?","a":"<p><code>indices[:split]</code> (20%) is used for training and the remaining 80% for validation. That looks reversed from the usual convention, so check it in your own code.</p>","hand":true},{"id":"pytorch-hands-on-f0024","card":"q-pytorch-hands-on-005-fashionmnist-preloaded-with-train-valida","sec":"pytorch-hands-on-s006","q":"How do you get one batch of images and labels from a DataLoader?","a":"<p>Make an iterator and call <code>next</code> on it.</p>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Python</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>dataiter = iter(trainloader)\nimages, labels = next(dataiter)</code></pre></div>","hand":true},{"id":"pytorch-hands-on-f0025","card":"q-pytorch-hands-on-006-custom-csv-dataset-tutors","sec":"pytorch-hands-on-s007","q":"What is the pipeline for turning a custom CSV into a tensor in PyTorch?","a":"<p>CSV, then a pandas DataFrame, then a tensor.</p>","hand":true},{"id":"pytorch-hands-on-f0026","card":"q-pytorch-hands-on-006-custom-csv-dataset-tutors","sec":"pytorch-hands-on-s007","q":"How do you read the first 50 rows of <code>Tutors.csv</code> and turn the <code>YearsExperience</code> column into a tensor?","a":"<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Python</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>df = pd.read_csv(Data_path, nrows=50)\nsessions_df = pd.DataFrame(df[&#x27;YearsExperience&#x27;])\ntrain_tensor = torch.tensor(sessions_df[&#x27;YearsExperience&#x27;].values)</code></pre></div>","hand":true},{"id":"pytorch-hands-on-f0027","card":"q-pytorch-hands-on-007-4-tensors-and-basic-operations","sec":"pytorch-hands-on-s008","q":"How do you create a 0-D, 1-D and 2-D tensor in PyTorch?","a":"<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Python</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>t0 = torch.tensor(1000)                     # 0-D (scalar)\nt1 = torch.tensor([9, 8, 7, 6])             # 1-D (vector)\nt2 = torch.tensor([[1, 2, 3], [7, 5, 3]])   # 2-D (matrix)</code></pre></div>","hand":true},{"id":"pytorch-hands-on-f0028","card":"q-pytorch-hands-on-007-4-tensors-and-basic-operations","sec":"pytorch-hands-on-s008","q":"What are the tensor ranks 0-D, 1-D, 2-D and 3-D+ called, and what are they typically used for?","a":"<div class=\"table-wrap\">\n  <table>\n    <thead><tr><th>Rank</th><th>Name</th><th>Typical use</th></tr></thead>\n    <tbody>\n      <tr><td>0-D</td><td>Scalar</td><td>Loss value</td></tr>\n      <tr><td>1-D</td><td>Vector</td><td>Features</td></tr>\n      <tr><td>2-D</td><td>Matrix</td><td>Tabular data, weights</td></tr>\n      <tr><td>3-D+</td><td>Tensor</td><td>Images, sequences</td></tr>\n    </tbody>\n  </table>\n</div>","hand":true},{"id":"pytorch-hands-on-f0029","card":"q-pytorch-hands-on-008-data-types","sec":"pytorch-hands-on-s009","q":"How do you set a tensor's dtype at creation and cast it afterwards in PyTorch?","a":"<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Python</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>a = torch.ones((2, 3), dtype=torch.int16)   # set type at creation\nb = a.to(dtype=torch.float32)               # cast</code></pre></div>","hand":true},{"id":"pytorch-hands-on-f0030","card":"q-pytorch-hands-on-008-data-types","sec":"pytorch-hands-on-s009","q":"Which PyTorch float dtypes exist and when is each used?","a":"<ul>\n  <li><code>float32</code>: default, most used.</li>\n  <li><code>float64</code>: rare, slow.</li>\n  <li><code>float16</code>: GPU speedup.</li>\n  <li><code>bfloat16</code>: TPUs / newer GPUs.</li>\n</ul>","hand":true},{"id":"pytorch-hands-on-f0031","card":"q-pytorch-hands-on-008-data-types","sec":"pytorch-hands-on-s009","q":"Which PyTorch integer dtypes exist and which is most common?","a":"<p><code>int64</code> is the most common (classification labels). Others are <code>int32</code>, <code>int16</code>, <code>int8</code> and <code>uint8</code> (quantization).</p>","hand":true},{"id":"pytorch-hands-on-f0032","card":"q-pytorch-hands-on-008-data-types","sec":"pytorch-hands-on-s009","q":"Which bool and complex dtypes does PyTorch have?","a":"<p><code>bool</code>, and <code>complex64</code> / <code>complex128</code> (rare in DL).</p>","hand":true},{"id":"pytorch-hands-on-f0033","card":"q-pytorch-hands-on-009-size-and-dimensionality","sec":"pytorch-hands-on-s010","q":"How do you read a tensor's shape in PyTorch, and which two calls are equivalent?","a":"<p><code>.size()</code> and <code>.shape</code> are equivalent. Both return a <code>torch.Size</code>.</p>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Python</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>print(t1.size())        # torch.Size([4])\nprint(t2.shape)         # torch.Size([2, 3])   (.size() and .shape are equivalent)</code></pre></div>","hand":true},{"id":"pytorch-hands-on-f0034","card":"q-pytorch-hands-on-009-size-and-dimensionality","sec":"pytorch-hands-on-s010","q":"How do you get a tensor's rank (number of dimensions)?","a":"<p><code>.ndimension()</code> and <code>.ndim</code> are equivalent.</p>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Python</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>print(t1.ndimension())  # 1\nprint(t2.ndim)          # 2   (&quot;rank&quot;; .ndimension() and .ndim are equivalent)</code></pre></div>","hand":true},{"id":"pytorch-hands-on-f0035","card":"q-pytorch-hands-on-009-size-and-dimensionality","sec":"pytorch-hands-on-s010","q":"How do you reshape a tensor in PyTorch, and when is it needed?","a":"<p>Use <code>.view(nrows, ncols)</code>. It is needed when a network's input layer expects a specific shape.</p>","hand":true},{"id":"pytorch-hands-on-f0036","card":"q-pytorch-hands-on-010-operations","sec":"pytorch-hands-on-s011","q":"How do tensor operations behave by default in PyTorch, and what must hold for shapes?","a":"<p>They are element-wise. Shapes must match or be broadcastable.</p>","hand":true},{"id":"pytorch-hands-on-f0037","card":"q-pytorch-hands-on-010-operations","sec":"pytorch-hands-on-s011","q":"What do <code>u + v</code> and <code>u - v</code> return for <code>u = torch.tensor([1.0, 2.0])</code> and <code>v = torch.tensor([3.0, 4.0])</code>?","a":"<p><code>u + v</code> is <code>tensor([4., 6.])</code> and <code>u - v</code> is <code>tensor([-2., -2.])</code>.</p>","hand":true},{"id":"pytorch-hands-on-f0038","card":"q-pytorch-hands-on-010-operations","sec":"pytorch-hands-on-s011","q":"Which common functions does PyTorch offer to round, take absolute values or limit tensor values?","a":"<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Python</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>torch.abs(a)\ntorch.ceil(a)\ntorch.floor(a)\ntorch.clamp(a, -0.5, 0.5)      # restrict values to [-0.5, 0.5]</code></pre></div>","hand":true},{"id":"pytorch-hands-on-f0039","card":"q-pytorch-hands-on-010-operations","sec":"pytorch-hands-on-s011","q":"How do you create a random 2x4 tensor with values in [-1, 1]?","a":"<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Python</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>a = torch.rand(2, 4) * 2 - 1   # random 2x4 in [-1, 1]</code></pre></div>","hand":true},{"id":"pytorch-hands-on-f0040","card":"q-pytorch-hands-on-010-operations","sec":"pytorch-hands-on-s011","q":"What do <code>mean()</code>, <code>max()</code> and <code>min()</code> return for <code>torch.tensor([1, 2, 3, 4, 5], dtype=torch.float32)</code>?","a":"<p><code>x.mean()</code> is <code>tensor(3.)</code>, <code>x.max()</code> is <code>tensor(5.)</code> and <code>x.min()</code> is <code>tensor(1.)</code>.</p>","hand":true},{"id":"pytorch-hands-on-f0041","card":"q-pytorch-hands-on-010-operations","sec":"pytorch-hands-on-s011","q":"What do <code>torch.sin</code> and <code>torch.cos</code> return for <code>torch.tensor([0, np.pi / 2, np.pi])</code>?","a":"<p><code>torch.sin(x)</code> is <code>tensor([0., 1., 0.])</code> and <code>torch.cos(x)</code> is <code>tensor([1., 0., -1.])</code>.</p>","hand":true},{"id":"pytorch-hands-on-f0042","card":"q-pytorch-hands-on-010-operations","sec":"pytorch-hands-on-s011","q":"How do you make 1000 evenly spaced points from -pi/2 to pi/2 in PyTorch?","a":"<p>Use <code>torch.linspace</code>.</p>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Python</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>pi = torch.linspace(-np.pi/2, np.pi/2, steps=1000)</code></pre></div>","hand":true},{"id":"pytorch-hands-on-f0043","card":"q-pytorch-hands-on-010-operations","sec":"pytorch-hands-on-s011","q":"Which other operation categories does PyTorch offer, and how do they differ from NumPy?","a":"<p>More reductions (<code>std</code>, <code>prod</code>, <code>unique</code>), inverse trig (<code>asin</code>, <code>acos</code>), bitwise (AND/OR/XOR), comparisons (<code>eq</code>, <code>gt</code>, <code>lt</code>, <code>ge</code>, <code>le</code>) and linear algebra (matmul, dot). Unlike NumPy, all ops support autograd and GPU.</p>","hand":true},{"id":"pytorch-hands-on-f0044","card":"q-pytorch-hands-on-011-broadcasting","sec":"pytorch-hands-on-s012","q":"What is broadcasting in PyTorch and why use it?","a":"<p>It lets tensors of different shapes combine without copying data. It is memory efficient, for example when applying weights across a batch. Semantics match NumPy.</p>","hand":true},{"id":"pytorch-hands-on-f0045","card":"q-pytorch-hands-on-011-broadcasting","sec":"pytorch-hands-on-s012","q":"What are the broadcasting rules in PyTorch?","a":"<p>Compare shapes <strong>from the last dimension to the first</strong>. Each pair must satisfy one of:</p>\n<ul>\n  <li>sizes are equal,</li>\n  <li>one of them is 1 (stretched),</li>\n  <li>the dimension is absent in one tensor (treated as 1).</li>\n</ul>\n<p>Tensors cannot be empty (at least one dimension).</p>","hand":true},{"id":"pytorch-hands-on-f0046","card":"q-pytorch-hands-on-011-broadcasting","sec":"pytorch-hands-on-s012","q":"What shape results from adding <code>torch.ones(5, 1)</code> and <code>torch.ones(1, 4)</code>?","a":"<p><code>(5, 4)</code>.</p>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Python</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>a = torch.ones(5, 1)     # (5, 1)\nb = torch.ones(1, 4)     # (1, 4)\nc = a + b                # (5, 4)</code></pre></div>","hand":true},{"id":"pytorch-hands-on-f0047","card":"q-pytorch-hands-on-011-broadcasting","sec":"pytorch-hands-on-s012","q":"With <code>a = torch.ones(4, 3, 2)</code>, what shape do <code>a * torch.rand(3, 2)</code>, <code>a * torch.rand(3, 1)</code> and <code>a * torch.rand(1, 2)</code> give, and why?","a":"<p>All give <code>(4, 3, 2)</code>.</p>\n<ul>\n  <li><code>rand(3, 2)</code>: the leading dimension is missing.</li>\n  <li><code>rand(3, 1)</code>: the last dimension is 1, so it is stretched.</li>\n  <li><code>rand(1, 2)</code>: the middle dimension is 1, so it is stretched.</li>\n</ul>","hand":true},{"id":"pytorch-hands-on-f0048","card":"q-pytorch-hands-on-012-pytorch-numpy-bridge","sec":"pytorch-hands-on-s013","q":"How do you convert between a NumPy array and a PyTorch tensor?","a":"<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Python</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>pytorch_tensor = torch.from_numpy(numpy_array)  # NumPy -&gt; tensor\nnumpy_rand = pytorch_rand.numpy()               # tensor -&gt; NumPy</code></pre></div>","hand":true},{"id":"pytorch-hands-on-f0049","card":"q-pytorch-hands-on-012-pytorch-numpy-bridge","sec":"pytorch-hands-on-s013","q":"Does converting between NumPy and PyTorch copy the data?","a":"<p>No. Both directions are zero-copy and <strong>share memory</strong> (CPU tensors). Changing one changes the other.</p>","hand":true},{"id":"pytorch-hands-on-f0050","card":"q-pytorch-hands-on-012-pytorch-numpy-bridge","sec":"pytorch-hands-on-s013","q":"What is the interview gotcha with the PyTorch and NumPy bridge, and how do you avoid it?","a":"<p>Mutating one changes the other. Use <code>.clone()</code> / <code>.copy()</code> to decouple.</p>","hand":true},{"id":"pytorch-hands-on-f0051","card":"q-pytorch-hands-on-012-pytorch-numpy-bridge","sec":"pytorch-hands-on-s013","q":"What dtype does a NumPy array from <code>np.ones((2, 3))</code> have, and what carries over with <code>torch.from_numpy</code>?","a":"<p>NumPy defaults to float64, and the tensor created from it shares the same memory.</p>","hand":true},{"id":"pytorch-hands-on-f0052","card":"q-pytorch-hands-on-013-6-autograd","sec":"pytorch-hands-on-s014","q":"What does PyTorch autograd do?","a":"<p>It tracks tensor operations and builds a <strong>dynamic computation graph</strong>. It computes gradients of the loss w.r.t. parameters for backpropagation.</p>","hand":true},{"id":"pytorch-hands-on-f0053","card":"q-pytorch-hands-on-013-6-autograd","sec":"pytorch-hands-on-s014","q":"Why does the dynamic graph matter in PyTorch autograd?","a":"<p>It allows flexible architectures (RNNs, transformers, conditional logic).</p>","hand":true},{"id":"pytorch-hands-on-f0054","card":"q-pytorch-hands-on-013-6-autograd","sec":"pytorch-hands-on-s014","q":"What are the 3 steps of the PyTorch training loop?","a":"<div class=\"table-wrap\">\n  <table>\n    <thead><tr><th>Step</th><th>Action</th><th>Phase</th></tr></thead>\n    <tbody>\n      <tr><td>1</td><td>Compute loss between prediction and label</td><td>Forward pass</td></tr>\n      <tr><td>2</td><td>Compute gradients of loss w.r.t. parameters</td><td>Backward pass (chain rule)</td></tr>\n      <tr><td>3</td><td>Update weights with optimizer (SGD, Adam)</td><td>Optimization</td></tr>\n    </tbody>\n  </table>\n</div>","hand":true},{"id":"pytorch-hands-on-f0055","card":"q-pytorch-hands-on-013-6-autograd","sec":"pytorch-hands-on-s014","q":"How do forward and backward passes work in PyTorch autograd?","a":"<p>Forward: each layer's output feeds the next. Backward: traverse from the output, collecting gradients with the chain rule.</p>","hand":true},{"id":"pytorch-hands-on-f0056","card":"q-pytorch-hands-on-013-6-autograd","sec":"pytorch-hands-on-s014","q":"What are <code>requires_grad=True</code> and <code>grad_fn</code> in PyTorch?","a":"<p>A tensor with <code>requires_grad=True</code> is a tracked leaf. <code>grad_fn</code> records the op that created a tensor.</p>","hand":true},{"id":"pytorch-hands-on-f0057","card":"q-pytorch-hands-on-013-6-autograd","sec":"pytorch-hands-on-s014","q":"What does this print: <code>x = torch.tensor([2.0], requires_grad=True)</code>, <code>y = x**2 + 3*x</code>, <code>y.backward()</code>, <code>print(x.grad)</code>?","a":"<p><code>dy/dx = 2x + 3 = 7</code> at x = 2.</p>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Python</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>x = torch.tensor([2.0], requires_grad=True)  # leaf tensor\ny = x**2 + 3*x\nprint(y.grad_fn)   # function that created the tensor\ny.backward()       # backward pass\nprint(x.grad)      # dy/dx = 2x + 3 = 7</code></pre></div>","hand":true},{"id":"pytorch-hands-on-f0058","card":"q-pytorch-hands-on-014-visualizing-the-graph-with-torchviz","sec":"pytorch-hands-on-s015","q":"In the torchviz example with <code>a = 2</code>, <code>b = 3</code>, <code>x = a * b</code>, <code>y = x + b</code>, <code>z = y ** 2</code>, what are <code>dz/da</code> and <code>dz/db</code>?","a":"<p><code>dz/da = 2*y * b = 54</code> and <code>dz/db = 2*y * (1 + a) = 72</code>. The values are x = 6, y = 9, z = 81.</p>","hand":true},{"id":"pytorch-hands-on-f0059","card":"q-pytorch-hands-on-014-visualizing-the-graph-with-torchviz","sec":"pytorch-hands-on-s015","q":"How do you render a PyTorch autograd graph to a PNG with torchviz?","a":"<p>Use <code>make_dot</code> and <code>.render</code>. It needs graphviz installed (for example via Homebrew).</p>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Python</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>make_dot(z, params={&quot;a&quot;: a, &quot;b&quot;: b}).render(&quot;autograd_graph&quot;, format=&quot;png&quot;)</code></pre></div>","hand":true},{"id":"pytorch-hands-on-f0060","card":"q-pytorch-hands-on-014-visualizing-the-graph-with-torchviz","sec":"pytorch-hands-on-s015","q":"How do you set the printed precision of tensors to 2 decimals?","a":"<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Python</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>torch.set_printoptions(precision=2)</code></pre></div>","hand":true},{"id":"pytorch-hands-on-f0061","card":"q-pytorch-hands-on-015-practical-rules","sec":"pytorch-hands-on-s016","q":"What does <code>with torch.no_grad()</code> do in PyTorch, and when do you use it?","a":"<p>Use it for inference. It saves memory.</p>","hand":true},{"id":"pytorch-hands-on-f0062","card":"q-pytorch-hands-on-015-practical-rules","sec":"pytorch-hands-on-s016","q":"What does <code>.detach()</code> do in PyTorch?","a":"<p>It cuts a tensor from the graph.</p>","hand":true},{"id":"pytorch-hands-on-f0063","card":"q-pytorch-hands-on-015-practical-rules","sec":"pytorch-hands-on-s016","q":"Why call <code>optimizer.zero_grad()</code> in PyTorch?","a":"<p>It resets gradients before <code>.backward()</code>, because gradients accumulate.</p>","hand":true},{"id":"pytorch-hands-on-f0064","card":"q-pytorch-hands-on-015-practical-rules","sec":"pytorch-hands-on-s016","q":"What is <code>torchviz</code> used for?","a":"<p>Debugging the autograd graph visually.</p>","hand":true},{"id":"pytorch-hands-on-f0065","card":"q-pytorch-hands-on-016-7-advanced-autograd","sec":"pytorch-hands-on-s017","q":"What does <code>torch.autograd.grad</code> do, and how does it differ from <code>.backward()</code>?","a":"<p>It returns gradients without touching <code>.grad</code>. It gives finer control and is the base for higher-order derivatives.</p>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Python</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>x = torch.tensor([2.0], requires_grad=True)\ny = x ** 3\ngrad = torch.autograd.grad(y, x)  # (3x^2,) -&gt; (12.,)\nprint(&quot;dy/dx =&quot;, grad[0])         # tensor([12.])</code></pre></div>","hand":true},{"id":"pytorch-hands-on-f0066","card":"q-pytorch-hands-on-016-7-advanced-autograd","sec":"pytorch-hands-on-s017","q":"How do you compute a second derivative in PyTorch?","a":"<p>Pass <code>create_graph=True</code> to keep the graph, so the first derivative can itself be differentiated.</p>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Python</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>dy_dx = torch.autograd.grad(y, x, create_graph=True)[0]\nd2y_dx2 = torch.autograd.grad(dy_dx, x)[0]   # 6x = 12</code></pre></div>","hand":true},{"id":"pytorch-hands-on-f0067","card":"q-pytorch-hands-on-016-7-advanced-autograd","sec":"pytorch-hands-on-s017","q":"When do you write a custom autograd <code>Function</code> in PyTorch, and what does <code>ctx.save_for_backward</code> do?","a":"<p>Use it for debugging, experiments and unsupported ops: you define forward and backward yourself. <code>ctx.save_for_backward</code> stashes tensors needed in backward.</p>","hand":true},{"id":"pytorch-hands-on-f0068","card":"q-pytorch-hands-on-016-7-advanced-autograd","sec":"pytorch-hands-on-s017","q":"How is a custom <code>Square</code> autograd Function written in PyTorch?","a":"<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Python</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>class Square(Function):\n    @staticmethod\n    def forward(ctx, input):\n        ctx.save_for_backward(input)\n        return input ** 2\n\n    @staticmethod\n    def backward(ctx, grad_output):\n        input, = ctx.saved_tensors\n        return grad_output * 2 * input</code></pre></div>","hand":true},{"id":"pytorch-hands-on-f0069","card":"q-pytorch-hands-on-016-7-advanced-autograd","sec":"pytorch-hands-on-s017","q":"How do you call the custom <code>Square</code> Function, and what gradient does it give at x = 3?","a":"<p>Use <code>Square.apply</code>. The gradient is 2 * 3 = 6.</p>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Python</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>x = torch.tensor([3.0], requires_grad=True)\nsquare = Square.apply\ny = square(x)\ny.backward()\nprint(&quot;Custom grad:&quot;, x.grad)  # 2 * 3 = 6</code></pre></div>","hand":true},{"id":"pytorch-hands-on-f0070","card":"q-pytorch-hands-on-016-7-advanced-autograd","sec":"pytorch-hands-on-s017","q":"What are a Jacobian and a Hessian?","a":"<p>A <strong>Jacobian</strong> is the matrix of first derivatives (vector-valued functions). A <strong>Hessian</strong> is the matrix of second derivatives.</p>","hand":true},{"id":"pytorch-hands-on-f0071","card":"q-pytorch-hands-on-016-7-advanced-autograd","sec":"pytorch-hands-on-s017","q":"How do you compute a Hessian in PyTorch?","a":"<p>Use <code>hessian</code> from <code>torch.autograd.functional</code>.</p>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Python</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>from torch.autograd.functional import hessian\nhess = hessian(f, x)</code></pre></div>","hand":true},{"id":"pytorch-hands-on-f0072","card":"q-pytorch-hands-on-016-7-advanced-autograd","sec":"pytorch-hands-on-s017","q":"What does <code>register_hook</code> do on a PyTorch tensor?","a":"<p>It inspects or modifies gradients as they flow during backward.</p>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Python</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>x.register_hook(print_grad)</code></pre></div>","hand":true},{"id":"pytorch-hands-on-f0073","card":"q-pytorch-hands-on-017-8-torchvision","sec":"pytorch-hands-on-s018","q":"What are the components of TorchVision?","a":"<p><strong>datasets</strong>, <strong>io</strong>, <strong>models</strong>, <strong>ops</strong>, <strong>transforms</strong> and <strong>utils</strong>.</p>","hand":true},{"id":"pytorch-hands-on-f0074","card":"q-pytorch-hands-on-017-8-torchvision","sec":"pytorch-hands-on-s018","q":"Which datasets does TorchVision provide?","a":"<p>CIFAR-10/100, ImageNet, Fashion-MNIST, EMNIST, CelebA. For detection and segmentation: COCO, Cityscapes, Caltech.</p>","hand":true},{"id":"pytorch-hands-on-f0075","card":"q-pytorch-hands-on-017-8-torchvision","sec":"pytorch-hands-on-s018","q":"What does the TorchVision <code>io</code> module do?","a":"<p>It reads and writes images as tensors, decodes JPEG/PNG from bytes, and handles video via FFmpeg.</p>","hand":true},{"id":"pytorch-hands-on-f0076","card":"q-pytorch-hands-on-017-8-torchvision","sec":"pytorch-hands-on-s018","q":"Which models does TorchVision include?","a":"<ul>\n  <li>Classification: ResNet, EfficientNet, VGG, MobileNet.</li>\n  <li>Detection: Faster R-CNN, Mask R-CNN, RetinaNet.</li>\n  <li>Segmentation: DeepLab.</li>\n</ul>\n<p>They are optionally ImageNet-pretrained and fine-tunable.</p>","hand":true},{"id":"pytorch-hands-on-f0077","card":"q-pytorch-hands-on-017-8-torchvision","sec":"pytorch-hands-on-s018","q":"What operators are in TorchVision <code>ops</code>?","a":"<p><code>batched_nms</code>, <code>box_area</code>, <code>clip_boxes_to_image</code>, <code>masks_to_boxes</code>, <code>remove_small_boxes</code>, <code>sigmoid_focal_loss</code>, <code>stochastic_depth</code>.</p>","hand":true},{"id":"pytorch-hands-on-f0078","card":"q-pytorch-hands-on-017-8-torchvision","sec":"pytorch-hands-on-s018","q":"What do TorchVision <code>transforms</code> and <code>utils</code> provide?","a":"<p>Transforms: resize, crop, flip, normalize, color jitter, grayscale, pad, compose. They work on PIL and tensors. Utils: <code>make_grid</code>, <code>save_image</code>, <code>draw_segmentation_masks</code>.</p>","hand":true},{"id":"pytorch-hands-on-f0079","card":"q-pytorch-hands-on-018-lab-image-captioning-blip-and-embeddings","sec":"pytorch-hands-on-s019","q":"How do you preprocess an image into a batch tensor of size 224x224 in TorchVision?","a":"<p>Compose <code>Resize</code> and <code>ToTensor</code>, then add a batch dimension with <code>unsqueeze(0)</code>.</p>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Python</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>preprocess = transforms.Compose([\n    transforms.Resize((224, 224)),\n    transforms.ToTensor(),\n])\nimage_tensor = preprocess(image).unsqueeze(0)  # add batch dimension</code></pre></div>","hand":true},{"id":"pytorch-hands-on-f0080","card":"q-pytorch-hands-on-018-lab-image-captioning-blip-and-embeddings","sec":"pytorch-hands-on-s019","q":"How do you load the BLIP image captioning model and generate a caption?","a":"<p>Load <code>BlipProcessor</code> and <code>BlipForConditionalGeneration</code> from <code>Salesforce/blip-image-captioning-base</code>, then call <code>generate</code> under <code>torch.no_grad()</code>.</p>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Python</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>processor = BlipProcessor.from_pretrained(&quot;Salesforce/blip-image-captioning-base&quot;)\nmodel = BlipForConditionalGeneration.from_pretrained(&quot;Salesforce/blip-image-captioning-base&quot;)\ninputs = processor(images=image, return_tensors=&quot;pt&quot;)\nwith torch.no_grad():\n    generated_ids = model.generate(**inputs)\n    caption = processor.decode(generated_ids[0], skip_special_tokens=True)</code></pre></div>","hand":true},{"id":"pytorch-hands-on-f0081","card":"q-pytorch-hands-on-018-lab-image-captioning-blip-and-embeddings","sec":"pytorch-hands-on-s019","q":"How do you get image embeddings with CLIP in the PyTorch lab?","a":"<p>Load <code>CLIPModel</code> and <code>CLIPProcessor</code> from <code>openai/clip-vit-base-patch32</code> and call <code>get_image_features</code>.</p>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Python</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>clip_model = CLIPModel.from_pretrained(&quot;openai/clip-vit-base-patch32&quot;)\nimage_features = clip_model.get_image_features(**inputs)</code></pre></div>","hand":true},{"id":"pytorch-hands-on-f0082","card":"q-pytorch-hands-on-018-lab-image-captioning-blip-and-embeddings","sec":"pytorch-hands-on-s019","q":"What are BLIP and CLIP each used for in the TorchVision lab?","a":"<p>BLIP generates captions. CLIP embeddings feed content-understanding models or similar-image retrieval via nearest-neighbor search.</p>","hand":true},{"id":"pytorch-hands-on-f0083","card":"q-pytorch-hands-on-019-lab-image-transforms","sec":"pytorch-hands-on-s020","q":"How do you add padding of several sizes to an image in TorchVision?","a":"<p>Use <code>T.Pad</code>.</p>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Python</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>padded_imgs = [T.Pad(padding=padding)(orig_img) for padding in (3, 10, 30, 50)]</code></pre></div>","hand":true},{"id":"pytorch-hands-on-f0084","card":"q-pytorch-hands-on-019-lab-image-transforms","sec":"pytorch-hands-on-s020","q":"How do you chain <code>RandomCrop</code> and <code>RandomHorizontalFlip</code> in TorchVision so they run on GPU tensors?","a":"<p>Chain them with <code>nn.Sequential</code>.</p>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Python</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>transforms = torch.nn.Sequential(\n    T.RandomCrop(224),\n    T.RandomHorizontalFlip(p=0.3),\n)</code></pre></div>","hand":true},{"id":"pytorch-hands-on-f0085","card":"q-pytorch-hands-on-019-lab-image-transforms","sec":"pytorch-hands-on-s020","q":"How do you apply <code>ColorJitter</code> and <code>RandomPerspective</code> in TorchVision?","a":"<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Python</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>jitter = T.ColorJitter(brightness=.5, hue=.3)\nperspective_transformer = T.RandomPerspective(distortion_scale=0.6, p=1.0)</code></pre></div>","hand":true},{"id":"pytorch-hands-on-f0086","card":"q-pytorch-hands-on-019-lab-image-transforms","sec":"pytorch-hands-on-s020","q":"How do you take center crops at several sizes in TorchVision?","a":"<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Python</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>center_crops = [T.CenterCrop(size=size)(orig_img) for size in (300, 500, 1000, orig_img.size)]</code></pre></div>","hand":true},{"id":"pytorch-hands-on-f0087","card":"q-pytorch-hands-on-019-lab-image-transforms","sec":"pytorch-hands-on-s020","q":"Why are random transforms useful, and how do you chain transforms?","a":"<p>They give different output each call, which is what makes them useful for <strong>data augmentation</strong>. Chain with <code>Compose</code> (PIL/tensor) or <code>nn.Sequential</code> (tensor, GPU).</p>","hand":true},{"id":"pytorch-hands-on-f0088","card":"q-pytorch-hands-on-019-lab-image-transforms","sec":"pytorch-hands-on-s020","q":"How do you read an image file as a tensor in TorchVision?","a":"<p>Use <code>read_image</code> from <code>torchvision.io</code>.</p>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Python</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>pottery1 = read_image(&#x27;pottery1.jpeg&#x27;)</code></pre></div>","hand":true},{"id":"pytorch-hands-on-f0089","card":"q-pytorch-hands-on-020-9-torchaudio","sec":"pytorch-hands-on-s021","q":"What are the components of TorchAudio?","a":"<p>datasets, <strong>io</strong>, <strong>transforms</strong>, <strong>functional</strong>, <strong>pipelines</strong>, <strong>models</strong> and <strong>utils</strong>. It mirrors TorchVision.</p>","hand":true},{"id":"pytorch-hands-on-f0090","card":"q-pytorch-hands-on-020-9-torchaudio","sec":"pytorch-hands-on-s021","q":"Which datasets does TorchAudio include?","a":"<p>LibriSpeech, Common Voice, GTZAN music genre, Speech Commands and YESNO.</p>","hand":true},{"id":"pytorch-hands-on-f0091","card":"q-pytorch-hands-on-020-9-torchaudio","sec":"pytorch-hands-on-s021","q":"What does the TorchAudio <code>io</code> module do?","a":"<p><code>load</code>, <code>save</code> and <code>info</code>. It handles WAV/FLAC/MP3 with a native or SoX backend.</p>","hand":true},{"id":"pytorch-hands-on-f0092","card":"q-pytorch-hands-on-020-9-torchaudio","sec":"pytorch-hands-on-s021","q":"What TorchAudio transforms exist, and how are they built?","a":"<p>They are <code>nn.Module</code>s: <code>MelSpectrogram</code>, <code>MFCC</code>, <code>Resample</code>, <code>Spectrogram</code>, <code>TimeStretch</code>, and <code>FrequencyMasking</code> / <code>TimeMasking</code> for augmentation.</p>","hand":true},{"id":"pytorch-hands-on-f0093","card":"q-pytorch-hands-on-020-9-torchaudio","sec":"pytorch-hands-on-s021","q":"How do TorchAudio <code>functional</code> and <code>transforms</code> differ?","a":"<p><code>functional</code> is stateless: <code>compute_deltas</code>, <code>phase_vocoder</code>, <code>resample</code>, <code>spectrogram</code>, <code>apply_codec</code>. Transforms are <code>nn.Module</code>s.</p>","hand":true},{"id":"pytorch-hands-on-f0094","card":"q-pytorch-hands-on-020-9-torchaudio","sec":"pytorch-hands-on-s021","q":"What are TorchAudio pipelines and what do they bundle?","a":"<p>Ready-made ASR with Wav2Vec2, HuBERT and Conformer, plus speaker verification/classification. A bundle holds the feature extractor, model, decoder, weights, sample rate and labels.</p>","hand":true},{"id":"pytorch-hands-on-f0095","card":"q-pytorch-hands-on-020-9-torchaudio","sec":"pytorch-hands-on-s021","q":"Which models does TorchAudio provide?","a":"<p>Wav2Vec2Model, Wav2Vec2ForCTC, HuBERT, Conformer, and Tacotron2 and WaveGlow for synthesis.</p>","hand":true},{"id":"pytorch-hands-on-f0096","card":"q-pytorch-hands-on-020-9-torchaudio","sec":"pytorch-hands-on-s021","q":"What do TorchAudio <code>utils</code> offer?","a":"<p><code>set_audio_backend</code> and <code>get_audio_backend</code>.</p>","hand":true},{"id":"pytorch-hands-on-f0097","card":"q-pytorch-hands-on-021-lab-speech-to-text","sec":"pytorch-hands-on-s022","q":"What is the flow of the TorchAudio speech-to-text lab?","a":"<p>Load audio, extract acoustic features frame by frame (one tensor per transformer layer, 12 for the base model), classify each frame, greedy-decode to a transcript. Optionally use Whisper instead.</p>","hand":true},{"id":"pytorch-hands-on-f0098","card":"q-pytorch-hands-on-021-lab-speech-to-text","sec":"pytorch-hands-on-s022","q":"How do you load the Wav2Vec2 ASR bundle and read its sample rate and labels?","a":"<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Python</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>bundle = torchaudio.pipelines.WAV2VEC2_ASR_BASE_960H\nprint(&quot;Sample Rate:&quot;, bundle.sample_rate)\nprint(&quot;Labels:&quot;, bundle.get_labels())\nmodel = bundle.get_model().to(device)</code></pre></div>","hand":true},{"id":"pytorch-hands-on-f0099","card":"q-pytorch-hands-on-021-lab-speech-to-text","sec":"pytorch-hands-on-s022","q":"Why does the speech-to-text lab override the <code>ssl</code> default context?","a":"<p>Only for certificate problems on download of the pretrained weights.</p>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Python</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>ssl._create_default_https_context = ssl._create_unverified_context</code></pre></div>","hand":true},{"id":"pytorch-hands-on-f0100","card":"q-pytorch-hands-on-021-lab-speech-to-text","sec":"pytorch-hands-on-s022","q":"How do you list, read and set the TorchAudio audio backend, and what must be installed?","a":"<p>Install with <code>pip3 install soundfile sox</code>.</p>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Python</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>print(torchaudio.list_audio_backends())     # installed backends\nprint(torchaudio.get_audio_backend())       # current backend\ntorchaudio.set_audio_backend(&quot;soundfile&quot;)   # or &quot;sox_io&quot;</code></pre></div>","hand":true},{"id":"pytorch-hands-on-f0101","card":"q-pytorch-hands-on-021-lab-speech-to-text","sec":"pytorch-hands-on-s022","q":"How do you load a WAV file and resample it to the model's rate in TorchAudio?","a":"<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Python</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>waveform, sample_rate = torchaudio.load(SPEECH_FILE)\nif sample_rate != bundle.sample_rate:\n    waveform = torchaudio.functional.resample(waveform, sample_rate, bundle.sample_rate)</code></pre></div>","hand":true},{"id":"pytorch-hands-on-f0102","card":"q-pytorch-hands-on-021-lab-speech-to-text","sec":"pytorch-hands-on-s022","q":"How do you extract Wav2Vec2 features, and how do you classify each frame?","a":"<p>Use <code>extract_features</code> for features and call the model for the emission, both under <code>torch.inference_mode()</code>.</p>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Python</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>with torch.inference_mode():\n    features, _ = model.extract_features(waveform)\nwith torch.inference_mode():\n    emission, _ = model(waveform)</code></pre></div>","hand":true},{"id":"pytorch-hands-on-f0103","card":"q-pytorch-hands-on-022-lab-speech-to-text","sec":"pytorch-hands-on-s022","q":"What is greedy CTC decoding?","a":"<p>Take the argmax class per frame, collapse consecutive repeats, and drop the blank token. It is the simplest decoder and needs no external dictionary.</p>","hand":true},{"id":"pytorch-hands-on-f0104","card":"q-pytorch-hands-on-022-lab-speech-to-text","sec":"pytorch-hands-on-s022","q":"How does the <code>GreedyCTCDecoder</code> forward method work?","a":"<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Python</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>indices = torch.argmax(emission, dim=-1)\nindices = torch.unique_consecutive(indices, dim=-1)\nindices = [i for i in indices if i != self.blank]\nreturn &quot;&quot;.join([self.labels[i] for i in indices])</code></pre></div>","hand":true},{"id":"pytorch-hands-on-f0105","card":"q-pytorch-hands-on-022-lab-speech-to-text","sec":"pytorch-hands-on-s022","q":"How do you use the <code>GreedyCTCDecoder</code> to get a transcript?","a":"<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Python</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>decoder = GreedyCTCDecoder(labels=bundle.get_labels())\ntranscript = decoder(emission[0])</code></pre></div>","hand":true},{"id":"pytorch-hands-on-f0106","card":"q-pytorch-hands-on-022-lab-speech-to-text","sec":"pytorch-hands-on-s022","q":"What is OpenAI Whisper in the TorchAudio lab, and what input does it expect?","a":"<p>An LLM-based alternative to Wav2Vec2. It expects 16 kHz mono audio.</p>","hand":true},{"id":"pytorch-hands-on-f0107","card":"q-pytorch-hands-on-022-lab-speech-to-text","sec":"pytorch-hands-on-s022","q":"How do you load Whisper and prepare audio for it?","a":"<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Python</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>processor = WhisperProcessor.from_pretrained(&quot;openai/whisper-base&quot;)\nmodel = WhisperForConditionalGeneration.from_pretrained(&quot;openai/whisper-base&quot;)\nwaveform = torchaudio.functional.resample(waveform, orig_freq=sample_rate, new_freq=16000)\nwaveform = waveform.mean(dim=0, keepdim=True)  # to mono</code></pre></div>","hand":true},{"id":"pytorch-hands-on-f0108","card":"q-pytorch-hands-on-022-lab-speech-to-text","sec":"pytorch-hands-on-s022","q":"How do you get a Whisper transcription?","a":"<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Python</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>inputs = processor(waveform.squeeze().numpy(), sampling_rate=sample_rate, return_tensors=&quot;pt&quot;)\nwith torch.no_grad():\n    predicted_ids = model.generate(inputs[&quot;input_features&quot;])\ntranscription = processor.batch_decode(predicted_ids, skip_special_tokens=True)[0]</code></pre></div>","hand":true},{"id":"pytorch-hands-on-f0109","card":"q-pytorch-hands-on-022-lab-speech-to-text","sec":"pytorch-hands-on-s022","q":"What must you do to audio before inference with a speech model in TorchAudio?","a":"<p>Always resample to the model's expected rate.</p>","hand":true},{"id":"pytorch-hands-on-f0110","card":"q-pytorch-hands-on-023-10-torchtext","sec":"pytorch-hands-on-s023","q":"What are the components of TorchText?","a":"<p><strong>datasets</strong>, <strong>preprocessing</strong>, <strong>transforms</strong>, <strong>pretrained embeddings</strong> and <strong>vocabularies</strong>. It works with <code>DataLoader</code>, <code>nn.Embedding</code> and normal train/eval loops.</p>","hand":true},{"id":"pytorch-hands-on-f0111","card":"q-pytorch-hands-on-023-10-torchtext","sec":"pytorch-hands-on-s023","q":"Which datasets does TorchText provide?","a":"<p>AG_News (classification), IMDB (sentiment), Multi30K (translation), PTB and WikiText-2/103 (language modeling).</p>","hand":true},{"id":"pytorch-hands-on-f0112","card":"q-pytorch-hands-on-023-10-torchtext","sec":"pytorch-hands-on-s023","q":"What does TorchText preprocessing cover?","a":"<p>Tokenization at word/char/subword level, normalization, padding, truncation and batching.</p>","hand":true},{"id":"pytorch-hands-on-f0113","card":"q-pytorch-hands-on-023-10-torchtext","sec":"pytorch-hands-on-s023","q":"Which transforms does TorchText have?","a":"<p><code>BasicEnglishNormalize</code>, <code>VocabTransform</code>, <code>Truncate</code>, <code>PadTransform</code>, <code>ToTensor</code>, <code>SentencePieceTokenizer</code>, <code>GPT2BPETokenizer</code>.</p>","hand":true},{"id":"pytorch-hands-on-f0114","card":"q-pytorch-hands-on-023-10-torchtext","sec":"pytorch-hands-on-s023","q":"Which pretrained embeddings and vocabulary features does TorchText have?","a":"<p>Embeddings: GloVe 6B/42B/840B, FastText, CharNGram. Vocabularies map token &lt;-&gt; index, integrate pretrained embeddings and support subword units.</p>","hand":true},{"id":"pytorch-hands-on-f0115","card":"q-pytorch-hands-on-024-lab-glove-preprocessing-gpt-2-generation","sec":"pytorch-hands-on-s024","q":"What is the flow of the TorchText GloVe + GPT-2 lab?","a":"<p>Tokenize, load GloVe, keep tokens that have vectors, mean-pool to a fixed 100-d session embedding, then prompt GPT-2.</p>","hand":true},{"id":"pytorch-hands-on-f0116","card":"q-pytorch-hands-on-024-lab-glove-preprocessing-gpt-2-generation","sec":"pytorch-hands-on-s024","q":"Which version constraint applies to the TorchText lab?","a":"<p>Match Torch and TorchText versions, for example Torch 2.2.0 + TorchText 0.17.0.</p>","hand":true},{"id":"pytorch-hands-on-f0117","card":"q-pytorch-hands-on-024-lab-glove-preprocessing-gpt-2-generation","sec":"pytorch-hands-on-s024","q":"How do you tokenize text and load GloVe 6B 100-d in TorchText?","a":"<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Python</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>tokenizer = get_tokenizer(&quot;basic_english&quot;)\ntokens = tokenizer(session_text)\nglove = GloVe(name=&#x27;6B&#x27;, dim=100)</code></pre></div>","hand":true},{"id":"pytorch-hands-on-f0118","card":"q-pytorch-hands-on-024-lab-glove-preprocessing-gpt-2-generation","sec":"pytorch-hands-on-s024","q":"How do you build a mean-pooled session embedding from GloVe vectors?","a":"<p>Stack the vectors of tokens found in GloVe and average them. Fall back to zeros if none are found.</p>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Python</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>token_vectors = [glove[token] for token in tokens if token in glove.stoi]\nif token_vectors:\n    session_embedding = torch.stack(token_vectors).mean(dim=0)   # mean-pooling\nelse:\n    session_embedding = torch.zeros(100)  # fallback if empty</code></pre></div>","hand":true},{"id":"pytorch-hands-on-f0119","card":"q-pytorch-hands-on-025-lab-glove-preprocessing-gpt-2-generation","sec":"pytorch-hands-on-s024","q":"How do you load GPT-2 for generation in the TorchText lab?","a":"<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Python</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>llm_tokenizer = GPT2Tokenizer.from_pretrained(&quot;gpt2&quot;)\nllm_model = GPT2LMHeadModel.from_pretrained(&quot;gpt2&quot;)\nllm_model.eval()</code></pre></div>","hand":true},{"id":"pytorch-hands-on-f0120","card":"q-pytorch-hands-on-025-lab-glove-preprocessing-gpt-2-generation","sec":"pytorch-hands-on-s024","q":"How do you generate text with GPT-2 using beam search?","a":"<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Python</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>outputs = llm_model.generate(\n    **inputs,\n    max_new_tokens=100,\n    num_beams=5,\n    no_repeat_ngram_size=2,\n    early_stopping=True\n)</code></pre></div>","hand":true},{"id":"pytorch-hands-on-f0121","card":"q-pytorch-hands-on-025-lab-glove-preprocessing-gpt-2-generation","sec":"pytorch-hands-on-s024","q":"What do <code>max_new_tokens</code>, <code>num_beams</code>, <code>no_repeat_ngram_size</code> and <code>early_stopping</code> do in GPT-2 <code>generate</code>?","a":"<div class=\"table-wrap\">\n  <table>\n    <thead><tr><th>Parameter</th><th>Effect</th></tr></thead>\n    <tbody>\n      <tr><td><code>max_new_tokens=100</code></td><td>Cap the length of the output</td></tr>\n      <tr><td><code>num_beams=5</code></td><td>Beam search, better quality than greedy</td></tr>\n      <tr><td><code>no_repeat_ngram_size=2</code></td><td>Blocks repeated bigrams</td></tr>\n      <tr><td><code>early_stopping=True</code></td><td>Stop when all beams finish</td></tr>\n    </tbody>\n  </table>\n</div>","hand":true},{"id":"pytorch-hands-on-f0122","card":"q-pytorch-hands-on-025-lab-glove-preprocessing-gpt-2-generation","sec":"pytorch-hands-on-s024","q":"How do you generate varied text with GPT-2 by sampling?","a":"<p>Set <code>do_sample=True</code> with <code>top_k</code>, <code>top_p</code> and <code>temperature</code>.</p>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Python</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>outputs = gpt2_model.generate(\n    inputs[&quot;input_ids&quot;],\n    max_new_tokens=50,\n    do_sample=True,\n    top_k=50,\n    top_p=0.95,\n    temperature=0.8\n)</code></pre></div>","hand":true},{"id":"pytorch-hands-on-f0123","card":"q-pytorch-hands-on-025-lab-glove-preprocessing-gpt-2-generation","sec":"pytorch-hands-on-s024","q":"Beam search vs sampling for GPT-2 generation?","a":"<p>Beam search is deterministic and coherent. Sampling with <code>top_k</code> / <code>top_p</code> / <code>temperature</code> is stochastic and diverse.</p>","hand":true}];
